<?php require_once __DIR__.'/includes/auth.php'; require_login(); $user=current_user(); $advice=$_POST['advice']??''; $messages=read_json(MESSAGES_FILE,[]); $record=['id'=>count($messages)+1,'email'=>$user['email'],'message'=>trim($advice),'sent_at'=>date('Y-m-d H:i:s')]; $messages[]=$record; write_json(MESSAGES_FILE,$messages); file_put_contents(LOG_DIR.'/sms_log.txt',date('c').' | '.$user['phone'].' | '.$record['message'].PHP_EOL,FILE_APPEND|LOCK_EX); flash('success','Advice sent to '.$user['phone'].' (SMS simulation).'); header('Location: dashboard.php'); exit;